{
  "name": "Trình tạo tem hiệu chuẩn",
  "description": "Một ứng dụng web chuyên dụng để tạo và in tem hiệu chuẩn cho các hệ thống công nghiệp. Hỗ trợ các kích thước tem và bố cục trang tùy chỉnh, với đầu ra PDF chính xác để đảm bảo chất lượng."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Không tìm thấy phần tử root để gắn vào");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { LabelData, LabelType, SheetLayout } from './types';
import { SMALL_LABEL_LAYOUT, LARGE_LABEL_LAYOUT } from './constants';
import { LabelForm } from './components/LabelForm';
import { LabelSheetPreview } from './components/LabelSheetPreview';
import { generatePdf } from './services/pdfGenerator';

const App: React.FC = () => {
    const [labelType, setLabelType] = useState<LabelType>(LabelType.Small);
    const [labelsToPrint, setLabelsToPrint] = useState<LabelData[]>([]);
    const [startIndex, setStartIndex] = useState<number>(1);
    const [error, setError] = useState<string>('');

    const currentLayout: SheetLayout = useMemo(() => {
        return labelType === LabelType.Small ? SMALL_LABEL_LAYOUT : LARGE_LABEL_LAYOUT;
    }, [labelType]);

    useEffect(() => {
        const quantity = labelsToPrint.length;
        if (quantity === 0) {
            setError('');
            return;
        }
        if (startIndex < 1) {
            setError('Vị trí bắt đầu phải lớn hơn 0.');
            return;
        }
        const remainingSlots = currentLayout.total - (startIndex - 1);
        if (quantity > remainingSlots) {
            setError(`Lỗi: số tem (${quantity}) vượt quá số vị trí còn trống (${remainingSlots}).`);
        } else {
            setError('');
        }
    }, [labelsToPrint, startIndex, currentLayout]);

    const addLabel = (data: Omit<LabelData, 'id'>) => {
        const newLabel: LabelData = { ...data, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
    };

    const removeLabel = (id: number) => {
        setLabelsToPrint(prev => prev.filter(label => label.id !== id));
    };

    const handleGeneratePdf = () => {
        if (error || labelsToPrint.length === 0) return;
        generatePdf(currentLayout, labelsToPrint, startIndex);
    };

    return (
        <div className="min-h-screen bg-slate-100 text-slate-800 p-4 sm:p-6 lg:p-8">
            <div className="max-w-7xl mx-auto">
                <header className="mb-8">
                    <h1 className="text-3xl font-bold text-slate-900">Trình tạo tem hiệu chuẩn</h1>
                    <p className="text-slate-600 mt-1">Giao diện chuyên nghiệp để tạo và in tem nhãn hiệu chuẩn chính xác.</p>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    {/* Control Panel */}
                    <aside className="lg:col-span-4 bg-white p-6 rounded-xl shadow-lg">
                        <h2 className="text-xl font-bold mb-6 border-b pb-4">Bảng điều khiển</h2>

                        <div className="space-y-6">
                            {/* Label Type Selection */}
                            <div>
                                <label htmlFor="label-type" className="block text-sm font-medium text-slate-700 mb-2">Loại tem</label>
                                <select
                                    id="label-type"
                                    value={labelType}
                                    onChange={(e) => setLabelType(e.target.value as LabelType)}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition"
                                >
                                    <option value={LabelType.Small}>Tem nhỏ ({SMALL_LABEL_LAYOUT.sizeW}x{SMALL_LABEL_LAYOUT.sizeH}mm)</option>
                                    <option value={LabelType.Large}>Tem lớn ({LARGE_LABEL_LAYOUT.sizeW}x{LARGE_LABEL_LAYOUT.sizeH}mm)</option>
                                </select>
                            </div>

                            {/* Start Index */}
                            <div>
                                <label htmlFor="start-index" className="block text-sm font-medium text-slate-700 mb-2">Vị trí tem bắt đầu in</label>
                                <input
                                    type="number"
                                    id="start-index"
                                    value={startIndex}
                                    onChange={(e) => setStartIndex(parseInt(e.target.value, 10) || 1)}
                                    min="1"
                                    max={currentLayout.total}
                                    className="w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition"
                                />
                            </div>

                            {/* Label Data Form */}
                            <LabelForm onSubmit={addLabel} />

                            {/* Action Button */}
                            <div className="pt-4 border-t">
                                <button
                                    onClick={handleGeneratePdf}
                                    disabled={!!error || labelsToPrint.length === 0}
                                    className="w-full flex items-center justify-center gap-2 bg-blue-600 text-white font-bold py-3 px-4 rounded-lg shadow-md hover:bg-blue-700 disabled:bg-slate-400 disabled:cursor-not-allowed transition-all duration-300"
                                >
                                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M6 2a2 2 0 00-2 2v12a2 2 0 002 2h8a2 2 0 002-2V4a2 2 0 00-2-2H6zm4 14a1 1 0 100-2 1 1 0 000 2zM6 5a1 1 0 011-1h6a1 1 0 110 2H7a1 1 0 01-1-1zm1 3a1 1 0 000 2h6a1 1 0 100-2H7z" clipRule="evenodd" /></svg>
                                    Xuất file PDF ({labelsToPrint.length} tem)
                                </button>
                                {error && <p className="text-red-600 text-sm mt-3 font-medium">{error}</p>}
                            </div>
                        </div>
                    </aside>

                    {/* Preview Area */}
                    <main className="lg:col-span-8">
                        <div className="bg-white p-6 rounded-xl shadow-lg h-full">
                           <h2 className="text-xl font-bold mb-2">Xem trước tem</h2>
                           <p className="text-sm text-slate-500 mb-6">Đây là bản xem trước của tờ tem. Tỷ lệ được điều chỉnh để vừa với màn hình.</p>

                           <div className="w-full aspect-[160/200] bg-slate-200 rounded-lg p-4 overflow-hidden">
                                <LabelSheetPreview
                                    layout={currentLayout}
                                    labels={labelsToPrint}
                                    startIndex={startIndex}
                                />
                           </div>
                        </div>
                         {labelsToPrint.length > 0 && (
                            <div className="bg-white p-6 rounded-xl shadow-lg mt-8">
                                <h3 className="text-lg font-bold mb-4">Danh sách tem sẽ in</h3>
                                <div className="max-h-60 overflow-y-auto">
                                    <ul className="divide-y divide-slate-200">
                                        {labelsToPrint.map((label, index) => (
                                            <li key={label.id} className="p-3 flex justify-between items-center">
                                                <div className="text-sm">
                                                    <p className="font-semibold text-slate-800">Tem #{index + 1}: {label.deviceId} - {label.deviceName}</p>
                                                    <p className="text-slate-500">Hiệu chuẩn: {label.calibrationDate} | Hạn: {label.nextCalibrationDate}</p>
                                                </div>
                                                <button onClick={() => removeLabel(label.id)} className="text-red-500 hover:text-red-700 font-medium text-xs">XÓA</button>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            </div>
                        )}
                    </main>
                </div>
            </div>
        </div>
    );
};

export default App;

export enum LabelType {
    Small = 'small',
    Large = 'large',
}

export interface LabelData {
    id: number;
    deviceId: string;
    deviceName: string;
    calibrationDate: string;
    nextCalibrationDate: string;
}

export interface SheetLayout {
    type: LabelType;
    paperWidth: number;
    paperHeight: number;
    cols: number;
    rows: number;
    total: number;
    sizeW: number;
    sizeH: number;
    gapX: number;
    gapY: number;
    marginTop: number;
    marginRight: number;
    marginBottom: number;
    marginLeft: number;
}

import React, { useState } from 'react';
import { LabelData } from '../types';

interface LabelFormProps {
    onSubmit: (data: Omit<LabelData, 'id'>) => void;
}

export const LabelForm: React.FC<LabelFormProps> = ({ onSubmit }) => {
    const [deviceId, setDeviceId] = useState('');
    const [deviceName, setDeviceName] = useState('');
    const [calibrationDate, setCalibrationDate] = useState('');
    const [nextCalibrationDate, setNextCalibrationDate] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!deviceId || !deviceName || !calibrationDate || !nextCalibrationDate) {
            alert('Vui lòng điền đầy đủ thông tin tem.');
            return;
        }
        onSubmit({ deviceId, deviceName, calibrationDate, nextCalibrationDate });
        // Reset form
        setDeviceId('');
        setDeviceName('');
        setCalibrationDate('');
        setNextCalibrationDate('');
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-4 border-t border-b py-6">
            <h3 className="text-md font-semibold text-slate-800">Nhập thông tin tem</h3>
            <div>
                <label htmlFor="device-id" className="block text-sm font-medium text-slate-700">Mã thiết bị</label>
                <input
                    type="text"
                    id="device-id"
                    value={deviceId}
                    onChange={(e) => setDeviceId(e.target.value)}
                    placeholder="Ví dụ: PR 108"
                    className="mt-1 w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    required
                />
            </div>
            <div>
                <label htmlFor="device-name" className="block text-sm font-medium text-slate-700">Tên thiết bị</label>
                <input
                    type="text"
                    id="device-name"
                    value={deviceName}
                    onChange={(e) => setDeviceName(e.target.value)}
                    placeholder="Ví dụ: THƯỚC DÂY THÉP"
                    className="mt-1 w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    required
                />
            </div>
            <div>
                <label htmlFor="calib-date" className="block text-sm font-medium text-slate-700">Thời điểm hiệu chuẩn</label>
                <input
                    type="text"
                    id="calib-date"
                    value={calibrationDate}
                    onChange={(e) => setCalibrationDate(e.target.value)}
                    placeholder="Định dạng: MM.YYYY"
                    className="mt-1 w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    pattern="\d{2}\.\d{4}"
                    title="Vui lòng nhập định dạng MM.YYYY"
                    required
                />
            </div>
            <div>
                <label htmlFor="next-calib-date" className="block text-sm font-medium text-slate-700">Hạn hiệu chuẩn tiếp theo</label>
                <input
                    type="text"
                    id="next-calib-date"
                    value={nextCalibrationDate}
                    onChange={(e) => setNextCalibrationDate(e.target.value)}
                    placeholder="Định dạng: MM.YYYY"
                    className="mt-1 w-full px-3 py-2 border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                    pattern="\d{2}\.\d{4}"
                    title="Vui lòng nhập định dạng MM.YYYY"
                    required
                />
            </div>
            <button
                type="submit"
                className="w-full bg-green-600 text-white font-bold py-2 px-4 rounded-lg shadow-sm hover:bg-green-700 transition"
            >
                Thêm vào danh sách in
            </button>
        </form>
    );
};

import React from 'react';
import { SheetLayout, LabelData } from '../types';
import { LabelDesign } from './LabelDesign';

interface LabelSheetPreviewProps {
    layout: SheetLayout;
    labels: LabelData[];
    startIndex: number;
}

export const LabelSheetPreview: React.FC<LabelSheetPreviewProps> = ({ layout, labels, startIndex }) => {
    const { paperWidth, paperHeight, cols, rows, total, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;

    const renderLabels = () => {
        const items = [];
        for (let i = 0; i < total; i++) {
            const row = Math.floor(i / cols);
            const col = i % cols;

            const x = marginLeft + col * (sizeW + gapX);
            const y = marginTop + row * (sizeH + gapY);

            const labelIndex = i - (startIndex - 1);
            const shouldPrint = i >= startIndex - 1 && labelIndex < labels.length;

            items.push(
                <g key={i} transform={`translate(${x}, ${y})`}>
                    <rect
                        width={sizeW}
                        height={sizeH}
                        fill={shouldPrint ? 'none' : 'rgba(100, 116, 139, 0.1)'}
                        stroke={shouldPrint ? '#3b82f6' : 'rgba(156, 163, 175, 0.4)'}
                        strokeWidth="0.2"
                        rx="0.5"
                    />
                    <text
                        x={sizeW / 2}
                        y={sizeH / 2}
                        textAnchor="middle"
                        dominantBaseline="central"
                        fill="rgba(156, 163, 175, 0.6)"
                        fontSize="3"
                        style={{ display: shouldPrint ? 'none' : 'block' }}
                    >
                        {i + 1}
                    </text>
                    {shouldPrint && labels[labelIndex] && (
                        <LabelDesign
                            layout={layout}
                            data={labels[labelIndex]}
                        />
                    )}
                </g>
            );
        }
        return items;
    };

    return (
        <svg
            viewBox={`0 0 ${paperWidth} ${paperHeight}`}
            width="100%"
            height="100%"
            className="bg-white rounded-md"
        >
            {renderLabels()}
        </svg>
    );
};

import React from 'react';
import { LabelData, SheetLayout, LabelType } from '../types';

interface LabelDesignProps {
    layout: SheetLayout;
    data: LabelData;
}

// Function to split long text for SVG tspan wrapping
const wrapText = (text: string, maxWidth: number, fontSize: number, charWidthRatio: number = 0.5) => {
    const maxChars = Math.floor(maxWidth / (fontSize * charWidthRatio));
    if (text.length <= maxChars) {
        return [text];
    }
    const words = text.split(' ');
    const lines = [];
    let currentLine = '';
    for (const word of words) {
        if ((currentLine + ' ' + word).length > maxChars) {
            lines.push(currentLine);
            currentLine = word;
        } else {
            currentLine = currentLine ? currentLine + ' ' + word : word;
        }
    }
    lines.push(currentLine);
    return lines;
};

export const LabelDesign: React.FC<LabelDesignProps> = ({ layout, data }) => {
    const { sizeW, sizeH } = layout;

    if (layout.type === LabelType.Small) {
        const fontSizePt = {
            jicv: 4.5,
            id: 4,
            name: 3.5,
            date: 3.5,
        };
        const nameLines = wrapText(data.deviceName, sizeW - 2, 0.352778 * fontSizePt.name, 0.5);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Inter, sans-serif" color="black">
                <text x={sizeW / 2} y="3.5" textAnchor="middle" fontSize={`${fontSizePt.jicv}pt`} fontWeight="bold">JICV</text>
                <text x={1.5} y="7.5" textAnchor="start" fontSize={`${fontSizePt.id}pt`} fontWeight="500">Mã TB: {data.deviceId}</text>

                <text x={1.5} y="11" textAnchor="start" fontSize={`${fontSizePt.name}pt`}>
                    {nameLines.map((line, i) => (
                        <tspan key={i} x={1.5} dy={i === 0 ? 0 : '1.2em'}>{line}</tspan>
                    ))}
                </text>

                <text x={sizeW / 2} y={sizeH - 2.5} textAnchor="middle" fontSize={`${fontSizePt.date}pt`}>
                    HC: {data.calibrationDate} | HHC: {data.nextCalibrationDate}
                </text>
            </svg>
        );
    }

    // Large Label Design
    const fontSizePt = {
        jicv: 6,
        id: 5,
        name: 5,
        dateLabel: 4,
        dateValue: 4.5,
    };

    return (
        <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Inter, sans-serif" color="black">
            <text x={sizeW / 2} y="5" textAnchor="middle" fontSize={`${fontSizePt.jicv}pt`} fontWeight="bold">JICV</text>

            <line x1="2" y1="8" x2={sizeW - 2} y2="8" stroke="black" strokeWidth="0.2" />

            <text x={2} y="13" textAnchor="start" fontSize={`${fontSizePt.id}pt`} fontWeight="500">Mã thiết bị: {data.deviceId}</text>
            <text x={2} y="18" textAnchor="start" fontSize={`${fontSizePt.name}pt`}>Tên thiết bị: {data.deviceName}</text>

            <text x={sizeW / 2} y="25" textAnchor="middle" fontSize={`${fontSizePt.dateLabel}pt`} fill="#333">Thời điểm hiệu chuẩn</text>
            <text x={sizeW / 2} y="28.5" textAnchor="middle" fontSize={`${fontSizePt.dateValue}pt`} fontWeight="500">{data.calibrationDate}</text>

            <text x={sizeW / 2} y="32.5" textAnchor="middle" fontSize={`${fontSizePt.dateLabel}pt`} fill="#333">Hạn hiệu chuẩn tiếp theo</text>
            <text x={sizeW / 2} y="36" textAnchor="middle" fontSize={`${fontSizePt.dateValue}pt`} fontWeight="500">{data.nextCalibrationDate}</text>
        </svg>
    );
};

import jsPDF from 'jspdf';
import { SheetLayout, LabelData, LabelType } from '../types';

// Function to split long text for PDF wrapping
const wrapTextPdf = (text: string, maxWidth: number, pdf: jsPDF, charWidthRatio: number = 0.5) => {
    const fontSize = pdf.getFontSize();
    const maxChars = Math.floor(maxWidth / (fontSize * charWidthRatio * 0.352778)); // pt to mm conversion
    if (text.length <= maxChars) {
        return [text];
    }
    const words = text.split(' ');
    const lines = [];
    let currentLine = '';
    for (const word of words) {
        if (pdf.getStringUnitWidth(currentLine + ' ' + word) * fontSize * 0.352778 > maxWidth) {
            lines.push(currentLine);
            currentLine = word;
        } else {
            currentLine = currentLine ? currentLine + ' ' + word : word;
        }
    }
    lines.push(currentLine);
    return lines;
};


const drawSmallLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW } = layout;
    pdf.setFont('Inter', 'bold').setFontSize(4.5).text('JICV', x + sizeW / 2, y + 3.5, { align: 'center' });
    pdf.setFont('Inter', 'normal').setFontSize(4).text(`Mã TB: ${data.deviceId}`, x + 1.5, y + 7.5);

    pdf.setFontSize(3.5);
    const nameLines = wrapTextPdf(data.deviceName, sizeW - 2, pdf);
    let lineOffset = 0;
    for (const line of nameLines) {
        pdf.text(line, x + 1.5, y + 11 + lineOffset);
        lineOffset += 2; // approx line height in mm
    }

    pdf.setFontSize(3.5).text(`HC: ${data.calibrationDate} | HHC: ${data.nextCalibrationDate}`, x + sizeW / 2, y + layout.sizeH - 2.5, { align: 'center' });
};

const drawLargeLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW } = layout;
    pdf.setFont('Inter', 'bold').setFontSize(6).text('JICV', x + sizeW / 2, y + 5, { align: 'center' });
    pdf.setLineWidth(0.2).line(x + 2, y + 8, x + sizeW - 2, y + 8);

    pdf.setFont('Inter', 'normal').setFontSize(5);
    pdf.text(`Mã thiết bị: ${data.deviceId}`, x + 2, y + 13);
    pdf.text(`Tên thiết bị: ${data.deviceName}`, x + 2, y + 18);

    pdf.setFont('Inter', 'normal').setFontSize(4).setTextColor('#333333');
    pdf.text('Thời điểm hiệu chuẩn', x + sizeW / 2, y + 25, { align: 'center' });
    pdf.setFont('Inter', 'medium').setFontSize(4.5).setTextColor('#000000');
    pdf.text(data.calibrationDate, x + sizeW / 2, y + 28.5, { align: 'center' });

    pdf.setFont('Inter', 'normal').setFontSize(4).setTextColor('#333333');
    pdf.text('Hạn hiệu chuẩn tiếp theo', x + sizeW / 2, y + 32.5, { align: 'center' });
    pdf.setFont('Inter', 'medium').setFontSize(4.5).setTextColor('#000000');
    pdf.text(data.nextCalibrationDate, x + sizeW / 2, y + 36, { align: 'center' });
};

export const generatePdf = (layout: SheetLayout, labels: LabelData[], startIndex: number) => {
    const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: [layout.paperWidth, layout.paperHeight],
    });

    // Embed Inter font if possible (requires font files, simplified for this context)
    // For production, you'd add the font files to the project and use pdf.addFileToVFS and pdf.addFont
    pdf.setFont('helvetica', 'sans-serif'); 

    const { cols, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;

    labels.forEach((labelData, index) => {
        const absoluteIndex = (startIndex - 1) + index;
        const row = Math.floor(absoluteIndex / cols);
        const col = absoluteIndex % cols;

        const x = marginLeft + col * (sizeW + gapX);
        const y = marginTop + row * (sizeH + gapY);

        if (layout.type === LabelType.Small) {
            drawSmallLabel(pdf, x, y, labelData, layout);
        } else {
            drawLargeLabel(pdf, x, y, labelData, layout);
        }
    });

    pdf.save(`tem-hieu-chuan-${layout.type}-${Date.now()}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { LabelData, LabelType, SheetLayout } from './types';
import { SMALL_LABEL_LAYOUT, LARGE_LABEL_LAYOUT } from './constants';
import { LabelForm } from './components/LabelForm';
import { LabelSheetPreview } from './components/LabelSheetPreview';
import { generatePdf } from './services/pdfGenerator';

const App: React.FC = () => {
    const [labelType, setLabelType] = useState<LabelType>(LabelType.Small);
    const [labelsToPrint, setLabelsToPrint] = useState<LabelData[]>([]);
    const [startIndex, setStartIndex] = useState<number>(1);
    const [error, setError] = useState<string>('');

    const currentLayout: SheetLayout = useMemo(() => {
        return labelType === LabelType.Small ? SMALL_LABEL_LAYOUT : LARGE_LABEL_LAYOUT;
    }, [labelType]);

    useEffect(() => {
        const quantity = labelsToPrint.length;
        if (quantity === 0) {
            setError('');
            return;
        }
        if (startIndex < 1) {
            setError('Vị trí bắt đầu phải lớn hơn 0.');
            return;
        }
        const remainingSlots = currentLayout.total - (startIndex - 1);
        if (quantity > remainingSlots) {
            setError(`Lỗi: số tem (${quantity}) vượt quá số vị trí còn trống (${remainingSlots}).`);
        } else {
            setError('');
        }
    }, [labelsToPrint, startIndex, currentLayout]);

    const addLabel = (data: Omit<LabelData, 'id'>) => {
        const newLabel: LabelData = { ...data, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
    };

    const removeLabel = (id: number) => {
        setLabelsToPrint(prev => prev.filter(label => label.id !== id));
    };

    const handleGeneratePdf = () => {
        if (error || labelsToPrint.length === 0) return;
        generatePdf(currentLayout, labelsToPrint, startIndex);
    };

    return (
