import React from 'react';
import { LabelData, SheetLayout, LabelType } from '../types';

interface LabelDesignProps {
    layout: SheetLayout;
    data: LabelData;
}

// Helper to wrap text based on approximate character width
const wrapText = (text: string, maxWidth: number, fontSizeMm: number) => {
    // Average char width factor for sans-serif (Inter/Arial) is roughly 0.55 of height
    const avgCharWidth = fontSizeMm * 0.55; 
    const maxChars = Math.floor(maxWidth / avgCharWidth);

    if (text.length <= maxChars) return [text];

    const words = text.split(' ');
    const lines: string[] = [];
    let currentLine = words[0] || '';

    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        if ((currentLine + ' ' + word).length <= maxChars) {
            currentLine += ' ' + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
};

export const LabelDesign: React.FC<LabelDesignProps> = ({ layout, data }) => {
    const { sizeW, sizeH } = layout;

    // --- SMALL LABEL DESIGN (16mm x 22mm) ---
    if (layout.type === LabelType.Small) {
        // Dimensions in mm
        const fontSize = {
            header: 2.2, // JICV
            id: 1.8,     // Device ID
            name: 1.6,   // Device Name
            date: 1.4    // Dates
        };

        const safeWidth = sizeW - 1; // 0.5mm padding each side
        // Calculate name wrapping
        // Allow up to 3 lines for name
        const nameLines = wrapText(data.deviceName, safeWidth, fontSize.name).slice(0, 3);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
                <rect width={sizeW} height={sizeH} fill="white" />

                {/* Header: JICV */}
                <text 
                    x={sizeW / 2} 
                    y={3} 
                    textAnchor="middle" 
                    fontSize={fontSize.header} 
                    fontWeight="bold" 
                    fill="#000"
                >JICV</text>

                {/* Device ID */}
                <text 
                    x={sizeW / 2} 
                    y={5.5} 
                    textAnchor="middle" 
                    fontSize={fontSize.id} 
                    fontWeight="bold" 
                    fill="#000"
                >{data.deviceId}</text>

                {/* Device Name (Dynamic Lines) */}
                {/* Start around y=8 */}
                {nameLines.map((line, i) => (
                    <text 
                        key={i} 
                        x={sizeW / 2} 
                        y={7.8 + (i * 1.9)} 
                        textAnchor="middle" 
                        fontSize={fontSize.name} 
                        fill="#000"
                    >{line}</text>
                ))}

                {/* Separator line at bottom */}
                <line x1={2} y1={sizeH - 6.5} x2={sizeW - 2} y2={sizeH - 6.5} stroke="#000" strokeWidth="0.1" opacity="0.5" />

                {/* Dates (Stacked at bottom) */}
                <text 
                    x={sizeW / 2} 
                    y={sizeH - 4.2} 
                    textAnchor="middle" 
                    fontSize={fontSize.date} 
                    fill="#000"
                >HC: {data.calibrationDate}</text>

                <text 
                    x={sizeW / 2} 
                    y={sizeH - 1.8} 
                    textAnchor="middle" 
                    fontSize={fontSize.date} 
                    fill="#000"
                >HHC: {data.nextCalibrationDate}</text>
            </svg>
        );
    }

    // --- LARGE LABEL DESIGN (19mm x 36mm) ---
    // More vertical space available
    const fontSize = {
        header: 3.5,
        id: 2.5,
        nameLabel: 1.8,
        name: 2.2,
        dateLabel: 1.8,
        date: 2.2
    };

    const safeWidth = sizeW - 2;
    const nameLines = wrapText(data.deviceName, safeWidth, fontSize.name).slice(0, 3);

    return (
        <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
            <rect width={sizeW} height={sizeH} fill="white" />

            {/* JICV */}
            <text x={sizeW / 2} y={4.5} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>

            <line x1={2} y1={6} x2={sizeW - 2} y2={6} stroke="black" strokeWidth="0.3" />

            {/* ID */}
            <text x={sizeW / 2} y={9.5} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>

            {/* Name */}
            {nameLines.map((line, i) => (
                <text key={i} x={sizeW / 2} y={13 + (i * 2.5)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
            ))}

            {/* Dates */}
            <g transform={`translate(0, ${sizeH - 12})`}>
                <text x={sizeW / 2} y={0} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Hiệu chuẩn</text>
                <text x={sizeW / 2} y={3} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>

                <text x={sizeW / 2} y={7} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Tiếp theo</text>
                <text x={sizeW / 2} y={10} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </g>
        </svg>
    );
};

import jsPDF from 'jspdf';
import { SheetLayout, LabelData, LabelType } from '../types';

// Helper: Convert mm font size to pt for jsPDF (1 mm approx 2.835 pt)
const mmToPt = (mm: number) => mm * 2.83465;

// Helper: Wrap text for PDF
// Estimates character width to split lines
const wrapTextPdf = (text: string, maxWidthMm: number, fontSizeMm: number) => {
    const avgCharWidthMm = fontSizeMm * 0.55; 
    const maxChars = Math.floor(maxWidthMm / avgCharWidthMm);

    if (text.length <= maxChars) return [text];

    const words = text.split(' ');
    const lines: string[] = [];
    let currentLine = words[0] || '';

    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        if ((currentLine + ' ' + word).length <= maxChars) {
            currentLine += ' ' + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
};

const drawSmallLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;

    // Font Config (Matches LabelDesign.tsx)
    const fontSize = {
        header: 2.2, // JICV
        id: 1.8,     // Device ID
        name: 1.6,   // Device Name
        date: 1.4    // Dates
    };

    pdf.setTextColor(0, 0, 0);

    // 1. Header: JICV
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(mmToPt(fontSize.header));
    pdf.text('JICV', centerX, y + 3, { align: 'center' });

    // 2. Device ID
    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId, centerX, y + 5.5, { align: 'center' });

    // 3. Device Name (Wrapped)
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));

    const safeWidth = sizeW - 1;
    const nameLines = wrapTextPdf(data.deviceName, safeWidth, fontSize.name).slice(0, 3);

    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 7.8 + (i * 1.9), { align: 'center' });
    });

    // 4. Separator Line
    pdf.setLineWidth(0.1);
    pdf.setDrawColor(150); // Grayish
    pdf.line(x + 2, y + sizeH - 6.5, x + sizeW - 2, y + sizeH - 6.5);
    pdf.setDrawColor(0); // Reset to black

    // 5. Dates
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(`HC: ${data.calibrationDate}`, centerX, y + sizeH - 4.2, { align: 'center' });
    pdf.text(`HHC: ${data.nextCalibrationDate}`, centerX, y + sizeH - 1.8, { align: 'center' });
};

const drawLargeLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;

    // Font Config (Matches LabelDesign.tsx)
    const fontSize = {
        header: 3.5,
        id: 2.5,
        nameLabel: 1.8,
        name: 2.2,
        dateLabel: 1.8,
        date: 2.2
    };

    pdf.setTextColor(0, 0, 0);

    // Header
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(mmToPt(fontSize.header));
    pdf.text('JICV', centerX, y + 4.5, { align: 'center' });

    // Line
    pdf.setLineWidth(0.3);
    pdf.line(x + 2, y + 6, x + sizeW - 2, y + 6);

    // ID
    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId, centerX, y + 9.5, { align: 'center' });

    // Name
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));
    const safeWidth = sizeW - 2;
    const nameLines = wrapTextPdf(data.deviceName, safeWidth, fontSize.name).slice(0, 3);
    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 13 + (i * 2.5), { align: 'center' });
    });

    // Dates Section
    const footerY = y + sizeH - 12;

    pdf.setTextColor(80, 80, 80); // Gray
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Hiệu chuẩn', centerX, footerY, { align: 'center' });

    pdf.setTextColor(0, 0, 0); // Black
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate, centerX, footerY + 3, { align: 'center' });

    pdf.setTextColor(80, 80, 80); // Gray
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Tiếp theo', centerX, footerY + 7, { align: 'center' });

    pdf.setTextColor(0, 0, 0); // Black
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.nextCalibrationDate, centerX, footerY + 10, { align: 'center' });
};

export const generatePdf = (layout: SheetLayout, labels: LabelData[], startIndex: number) => {
    const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: [layout.paperWidth, layout.paperHeight],
    });

    const { cols, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;

    labels.forEach((labelData, index) => {
        const absoluteIndex = (startIndex - 1) + index;
        const row = Math.floor(absoluteIndex / cols);
        const col = absoluteIndex % cols;

        const x = marginLeft + col * (sizeW + gapX);
        const y = marginTop + row * (sizeH + gapY);

        if (layout.type === LabelType.Small) {
            drawSmallLabel(pdf, x, y, labelData, layout);
        } else {
            drawLargeLabel(pdf, x, y, labelData, layout);
        }
    });

    pdf.save(`tem-hieu-chuan-${layout.type}-${Date.now()}.pdf`);
};

