export const generatePdf = async (layout: SheetLayout, labels: LabelData[], startIndex: number) => {
    const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: [layout.paperWidth, layout.paperHeight],
    });

    // Load custom fonts to support Vietnamese characters
    await loadFonts(pdf);

    const { cols, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;

    labels.forEach((labelData, index) => {
        const absoluteIndex = (startIndex - 1) + index;
        const row = Math.floor(absoluteIndex / cols);
        const col = absoluteIndex % cols;

        const x = marginLeft + col * (sizeW + gapX);
        const y = marginTop + row * (sizeH + gapY);

        if (layout.type === LabelType.Small) {
            drawSmallLabel(pdf, x, y, labelData, layout);
        } else {
            drawLargeLabel(pdf, x, y, labelData, layout);
        }
    });

    pdf.save(`tem-hieu-chuan-${layout.type}-${Date.now()}.pdf`);
};

import { SheetLayout, LabelType } from './types';

// Paper size: 160mm x 200mm
// Small Label: 16mm x 22mm (9 cols, 8 rows)
// Calculation Check:
// Width: 9 * 16mm (144mm) + 8 * 1mm gaps (8mm) = 152mm. 
// Margin Left/Right: (160 - 152) / 2 = 4mm.
// Height: 8 * 22mm (176mm) + 7 * 2mm gaps (14mm) = 190mm.
// Margin Top/Bottom: (200 - 190) / 2 = 5mm.

export const SMALL_LABEL_LAYOUT: SheetLayout = {
    type: LabelType.Small,
    paperWidth: 160,
    paperHeight: 200,
    cols: 9,
    rows: 8,
    total: 72,
    sizeW: 16,
    sizeH: 22,
    gapX: 1.0, // Reduced from 2 to fit width
    gapY: 2.0, // Reduced from 3 to fit height
    marginTop: 5,
    marginRight: 4,
    marginBottom: 5,
    marginLeft: 4,
};

// Paper size: 160mm x 200mm
// Large Label: 19mm x 36mm (8 cols, 5 rows)
// Calculation Check:
// Width: 8 * 19mm (152mm) + 7 * 0.5mm gaps (3.5mm) = 155.5mm.
// Margin Left/Right: (160 - 155.5) / 2 = 2.25mm.
