    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(`HC: ${data.calibrationDate}`, centerX, y + sizeH - 4.0, { align: 'center' });
    pdf.text(`HHC: ${data.nextCalibrationDate}`, centerX, y + sizeH - 2.0, { align: 'center' });
