// Paper size: 160mm x 200mm
// Large Label: 19mm x 36mm (8 cols, 5 rows)
// Calculation Check:
// Width: 8 * 19mm (152mm) + 7 * 0.5mm gaps (3.5mm) = 155.5mm.
// Margin Left/Right: (160 - 155.5) / 2 = 2.25mm.
// Height: 5 * 36mm (180mm) + 4 * 2.5mm gaps (10mm) = 190mm.
// Margin Top/Bottom: (200 - 190) / 2 = 5mm.

export const LARGE_LABEL_LAYOUT: SheetLayout = {
    type: LabelType.Large,
    paperWidth: 160,
    paperHeight: 200,
    cols: 8,
    rows: 5,
    total: 40,
    sizeW: 19,
    sizeH: 36,
    gapX: 0.5,
