                {/* Header: JICV */}
                <text 
                    x={sizeW / 2} 
                    y={3.2} 
                    textAnchor="middle" 
                    fontSize={fontSize.header} 
                    fontWeight="bold" 
                    fill="#000"
                >JICV</text>

                {/* Device ID */}
                <text 
                    x={sizeW / 2} 
                    y={6.2} 
                    textAnchor="middle" 
                    fontSize={fontSize.id} 
                    fontWeight="bold" 
                    fill="#000"
                >{data.deviceId}</text>

                {/* Device Name (Dynamic Lines) */}
                {nameLines.map((line, i) => (
                    <text 
                        key={i} 
                        x={sizeW / 2} 
                        y={8.8 + (i * 1.7)} 
                        textAnchor="middle" 
                        fontSize={fontSize.name} 
                        fill="#000"
                    >{line}</text>
                ))}

