                    x={sizeW / 2} 
                    y={sizeH - 4.0} 
                    textAnchor="middle" 
                    fontSize={fontSize.date} 
                    fill="#000"
                >HC: {data.calibrationDate}</text>

                <text 
                    x={sizeW / 2} 
                    y={sizeH - 2.0} 
                    textAnchor="middle" 
                    fontSize={fontSize.date} 
                    fill="#000"
                >HHC: {data.nextCalibrationDate}</text>
            </svg>
        );
    }

    // --- LARGE LABEL DESIGN (19mm x 36mm) ---
    const fontSize = {
        header: 2.8,
        id: 2.8,     
        nameLabel: 1.6,
        name: 1.8,
        dateLabel: 1.6,
        date: 1.8
    };

    const safeWidth = sizeW - 3;
    const nameLines = wrapText(data.deviceName, safeWidth, fontSize.name).slice(0, 3);

    return (
        <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
            <rect width={sizeW} height={sizeH} fill="white" />

            {/* JICV */}
            <text x={sizeW / 2} y={5.0} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>

            <line x1={3} y1={6.5} x2={sizeW - 3} y2={6.5} stroke="black" strokeWidth="0.2" />

            {/* ID */}
            <text x={sizeW / 2} y={10.5} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>

            {/* Name */}
            {nameLines.map((line, i) => (
                <text key={i} x={sizeW / 2} y={14.5 + (i * 2.2)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
            ))}

            {/* Dates */}
            <g transform={`translate(0, ${sizeH - 11})`}>
                <text x={sizeW / 2} y={0} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Hiệu chuẩn</text>
                <text x={sizeW / 2} y={2.8} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>

                <text x={sizeW / 2} y={6.2} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Tiếp theo</text>
                <text x={sizeW / 2} y={9.0} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </g>
        </svg>
    );
};

