const App: React.FC = () => {
    const [labelType, setLabelType] = useState<LabelType>(LabelType.Small);
    const [labelsToPrint, setLabelsToPrint] = useState<LabelData[]>([]);
    const [startIndex, setStartIndex] = useState<number>(1);

    // State for manual calibration offsets
    const [offsetX, setOffsetX] = useState<number>(0); // Margin Left adjustment
    const [offsetY, setOffsetY] = useState<number>(0); // Margin Top adjustment

    const [error, setError] = useState<string>('');
    const [isGenerating, setIsGenerating] = useState<boolean>(false);

    const currentLayout: SheetLayout = useMemo(() => {
        const baseLayout = labelType === LabelType.Small ? SMALL_LABEL_LAYOUT : LARGE_LABEL_LAYOUT;
        return {
            ...baseLayout,
            // Apply offsets to margins
            marginLeft: baseLayout.marginLeft + offsetX,
            marginTop: baseLayout.marginTop + offsetY,
        };
    }, [labelType, offsetX, offsetY]);

    useEffect(() => {
        const quantity = labelsToPrint.length;
        if (quantity === 0) {
            setError('');
            return;
        }
        if (startIndex < 1) {
            setError('Vị trí bắt đầu phải lớn hơn 0.');
            return;
        }
        const remainingSlots = currentLayout.total - (startIndex - 1);
        if (quantity > remainingSlots) {
            setError(`Lỗi: số tem (${quantity}) vượt quá số vị trí còn trống (${remainingSlots}).`);
        } else {
            setError('');
        }
    }, [labelsToPrint, startIndex, currentLayout]);

    const addLabel = (data: Omit<LabelData, 'id'>) => {
        const newLabel: LabelData = { ...data, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
