                                                    <div className="text-[10px] text-slate-400 mt-1 flex gap-2">
                                                        <span>HC: {label.calibrationDate}</span>
                                                        <span>•</span>
                                                        <span>Hạn: {label.nextCalibrationDate}</span>
                                                    </div>
                                                </div>
                                                <button 
                                                    onClick={() => removeLabel(label.id)}
