                                    <div>
                                        <label htmlFor="label-type" className="block text-xs font-semibold text-slate-700 mb-1.5">Loại tem</label>
                                        <select
                                            id="label-type"
                                            value={labelType}
                                            onChange={(e) => setLabelType(e.target.value as LabelType)}
