            alert('Có lỗi xảy ra khi tạo PDF. Vui lòng thử lại.');
        } finally {
            setIsGenerating(false);
        }
    };

    const resetCalibration = () => {
        setOffsetX(0);
        setOffsetY(0);
        setCustomGapY(0);
    };

    return (
        <div className="h-screen flex flex-col bg-slate-100 text-slate-800 font-sans overflow-hidden">
