    marginTop: 3.5,
    marginRight: 2.5,
    marginBottom: 3.5,
    marginLeft: 1.5,
};

// Indices to skip for Small Labels (Left column, Right column, Bottom row)
export const SMALL_LABEL_SKIPPED_INDICES = [
    // Left Column (1, 10, 19...)
