                    <img 
                        src="https://cdn-icons-png.flaticon.com/512/2997/2997295.png" 
                        alt="Logo" 
                        className="w-8 h-8 rounded-lg object-contain"
                    />
                    <h1 className="text-lg font-bold text-slate-900">Trình tạo tem hiệu chuẩn</h1>
