import React from 'react';
import { LabelData, SheetLayout, LabelType } from '../types';

interface LabelDesignProps {
    layout: SheetLayout;
    data: LabelData;
}

const wrapText = (text: string, maxWidth: number, fontSizeMm: number) => {
    const avgCharWidth = fontSizeMm * 0.6; 
    const maxChars = Math.floor(maxWidth / avgCharWidth);

    if (text.length <= maxChars) return [text];

    const words = text.split(' ');
    const lines: string[] = [];
    let currentLine = words[0] || '';

    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        if ((currentLine + ' ' + word).length <= maxChars) {
            currentLine += ' ' + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
};

export const LabelDesign: React.FC<LabelDesignProps> = ({ layout, data }) => {
    const { sizeW, sizeH } = layout;

    // --- RENDER GENERIC/FREE TEXT LABEL ---
    if (data.isGeneric) {
        const fSize = data.fontSize || 3.5;
        // When rotated, the available width for text wrapping is the label's height
        const wrapWidth = data.isRotated ? sizeH - 2 : sizeW - 2;
        const textLines = wrapText(data.content || '', wrapWidth, fSize);
        const lineHeight = fSize * 1.2;
        const totalHeight = textLines.length * lineHeight;

        // Calculate vertical start based on standard orientation logic
        // Then we wrap the group in a rotation transform
        const baseCanvasHeight = data.isRotated ? sizeW : sizeH;
        const baseCanvasWidth = data.isRotated ? sizeH : sizeW;
        const startY = (baseCanvasHeight - totalHeight) / 2 + (lineHeight * 0.8);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
                <rect width={sizeW} height={sizeH} fill="white" />
                <g transform={data.isRotated ? `rotate(90, ${sizeW / 2}, ${sizeH / 2})` : ''}>
                    {textLines.map((line, i) => (
                        <text 
                            key={i} 
                            x={baseCanvasWidth / 2} 
                            y={startY + (i * lineHeight)} 
                            textAnchor="middle" 
                            fontSize={fSize} 
                            fontWeight="bold" 
                            fill="#000"
                        >
                            {line}
                        </text>
                    ))}
                </g>
            </svg>
        );
    }

    // --- RENDER STANDARD CALIBRATION LABEL ---
    if (layout.type === LabelType.Small) {
        const fontSize = { header: 2.6, id: 2.7, name: 1.4, date: 2.1 };
        const safeWidth = sizeW - 2.0;
        const nameLines = wrapText(data.deviceName || '', safeWidth, fontSize.name).slice(0, 3);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
                <rect width={sizeW} height={sizeH} fill="white" />
                <text x={sizeW / 2} y={3.2} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>
                <line x1={2.5} y1={4.2} x2={sizeW - 2.5} y2={4.2} stroke="#000" strokeWidth="0.15" />
                <text x={sizeW / 2} y={7.2} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>
                {nameLines.map((line, i) => (
                    <text key={i} x={sizeW / 2} y={9.8 + (i * 1.7)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
                ))}
                <line x1={2.5} y1={sizeH - 6.0} x2={sizeW - 2.5} y2={sizeH - 6.0} stroke="#000" strokeWidth="0.15" opacity="0.5" />
                <text x={sizeW / 2} y={sizeH - 3.6} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>
                <text x={sizeW / 2} y={sizeH - 1.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </svg>
        );
    }

    // Large Label
    const fontSize = { header: 2.8, id: 3.8, name: 1.8, dateLabel: 1.6, date: 2.4 };
    const safeWidth = sizeW - 3;
    const nameLines = wrapText(data.deviceName || '', safeWidth, fontSize.name).slice(0, 3);

    return (
        <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
            <rect width={sizeW} height={sizeH} fill="white" />
            <text x={sizeW / 2} y={5.0} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>
            <line x1={3} y1={6.5} x2={sizeW - 3} y2={6.5} stroke="black" strokeWidth="0.2" />
            <text x={sizeW / 2} y={10.5} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>
            {nameLines.map((line, i) => (
                <text key={i} x={sizeW / 2} y={14.5 + (i * 2.2)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
            ))}
            <g transform={`translate(0, ${sizeH - 12})`}>
                <text x={sizeW / 2} y={0.5} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Hiệu chuẩn</text>
                <text x={sizeW / 2} y={3.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>
                <text x={sizeW / 2} y={6.5} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Tiếp theo</text>
                <text x={sizeW / 2} y={9.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </g>
        </svg>
    );
};

import jsPDF from 'jspdf';
import { SheetLayout, LabelData, LabelType } from '../types';
import { SMALL_LABEL_SKIPPED_INDICES, LARGE_LABEL_SKIPPED_INDICES } from '../constants';

const mmToPt = (mm: number) => mm * 2.83465;
const FONT_REGULAR_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.1.66/fonts/Roboto/Roboto-Regular.ttf';
const FONT_BOLD_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.1.66/fonts/Roboto/Roboto-Medium.ttf';

const loadFonts = async (pdf: jsPDF) => {
    const fetchFont = async (url: string) => {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to load font from ${url}`);
        const buffer = await response.arrayBuffer();
        let binary = '';
        const bytes = new Uint8Array(buffer);
        const len = bytes.byteLength;
        for (let i = 0; i < len; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return binary;
    };
    try {
        const [regularFont, boldFont] = await Promise.all([
            fetchFont(FONT_REGULAR_URL),
            fetchFont(FONT_BOLD_URL)
        ]);
        pdf.addFileToVFS('Roboto-Regular.ttf', regularFont);
        pdf.addFileToVFS('Roboto-Bold.ttf', boldFont);
        pdf.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
        pdf.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
        return true;
    } catch (error) {
        console.error("Error loading fonts:", error);
        return false;
    }
};

const wrapTextPdf = (text: string, maxWidthMm: number, fontSizeMm: number) => {
    const avgCharWidthMm = fontSizeMm * 0.6; 
    const maxChars = Math.floor(maxWidthMm / avgCharWidthMm);
    if (text.length <= maxChars) return [text];
    const words = text.split(' ');
    const lines: string[] = [];
    let currentLine = words[0] || '';
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        if ((currentLine + ' ' + word).length <= maxChars) {
            currentLine += ' ' + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
};

const drawGenericLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const fSize = data.fontSize || 3.5;

    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fSize));
    pdf.setTextColor(0, 0, 0);

    const wrapWidth = data.isRotated ? sizeH - 2 : sizeW - 2;
    const lines = wrapTextPdf(data.content || '', wrapWidth, fSize);
    const lineHeight = fSize * 1.2;
    const totalHeight = lines.length * lineHeight;

    const centerX = x + sizeW / 2;
    const centerY = y + sizeH / 2;

    if (data.isRotated) {
        // Rotated 90 degrees
        // The block is drawn relative to the center of the label
        const startOffset = -totalHeight / 2 + (lineHeight * 0.8);
        lines.forEach((line, i) => {
            // In jsPDF, 'angle' 90 rotates clockwise. 
            // We draw at center, rotated, with offset for lines.
            // X position for text alignment 'center' is the rotation pivot.
            // We use coordinate translation via angle property for simplicity.
            pdf.text(line, centerX - (startOffset + i * lineHeight), centerY, { align: 'center', angle: 90 });
        });
    } else {
        // Standard orientation
        const startY = y + (sizeH - totalHeight) / 2 + (lineHeight * 0.8);
        lines.forEach((line, i) => {
            pdf.text(line, centerX, startY + (i * lineHeight), { align: 'center' });
        });
    }
};

const drawSmallLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;
    const fontSize = { header: 2.6, id: 2.7, name: 1.4, date: 2.1 };
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.header));
    pdf.text('JICV', centerX, y + 3.2, { align: 'center' });
    pdf.setLineWidth(0.15);
    pdf.line(x + 2.5, y + 4.2, x + sizeW - 2.5, y + 4.2);
    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId || '', centerX, y + 7.2, { align: 'center' });
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));
    const nameLines = wrapTextPdf(data.deviceName || '', sizeW - 2.0, fontSize.name).slice(0, 3);
    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 9.8 + (i * 1.7), { align: 'center' });
    });
    pdf.setLineWidth(0.15);
    pdf.line(x + 2.5, y + sizeH - 6.0, x + sizeW - 2.5, y + sizeH - 6.0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate || '', centerX, y + sizeH - 3.6, { align: 'center' });
    pdf.text(data.nextCalibrationDate || '', centerX, y + sizeH - 1.2, { align: 'center' });
};

const drawLargeLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;
    const fontSize = { header: 2.8, id: 3.8, name: 1.8, dateLabel: 1.6, date: 2.4 };
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.header));
    pdf.text('JICV', centerX, y + 5.0, { align: 'center' });
    pdf.setLineWidth(0.2);
    pdf.line(x + 3, y + 6.5, x + sizeW - 3, y + 6.5);
    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId || '', centerX, y + 10.5, { align: 'center' });
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));
    const nameLines = wrapTextPdf(data.deviceName || '', sizeW - 3, fontSize.name).slice(0, 3);
    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 14.5 + (i * 2.2), { align: 'center' });
    });
    const footerY = y + sizeH - 12;
    pdf.setTextColor(80, 80, 80);
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Hiệu chuẩn', centerX, footerY + 0.5, { align: 'center' });
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate || '', centerX, footerY + 3.2, { align: 'center' });
    pdf.setTextColor(80, 80, 80);
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Tiếp theo', centerX, footerY + 6.5, { align: 'center' });
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.nextCalibrationDate || '', centerX, footerY + 9.2, { align: 'center' });
};

export const generatePdf = async (layout: SheetLayout, labels: LabelData[], startIndex: number) => {
    const pdf = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: [layout.paperWidth, layout.paperHeight],
    });
    await loadFonts(pdf);
    const { cols, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;
    const skippedIndices = layout.type === LabelType.Small ? SMALL_LABEL_SKIPPED_INDICES : LARGE_LABEL_SKIPPED_INDICES;
    let currentSlotIndex = startIndex;
    for (const labelData of labels) {
        while (skippedIndices.includes(currentSlotIndex)) {
            currentSlotIndex++;
        }
        if (currentSlotIndex > layout.total) break;
        const absoluteIndex0 = currentSlotIndex - 1;
        const row = Math.floor(absoluteIndex0 / cols);
        const col = absoluteIndex0 % cols;
        const x = marginLeft + col * (sizeW + gapX);
        const y = marginTop + row * (sizeH + gapY);

        if (labelData.isGeneric) {
            drawGenericLabel(pdf, x, y, labelData, layout);
        } else if (layout.type === LabelType.Small) {
            drawSmallLabel(pdf, x, y, labelData, layout);
        } else {
            drawLargeLabel(pdf, x, y, labelData, layout);
        }
        currentSlotIndex++;
    }
    pdf.save(`tem-tong-hop-${layout.type}-${Date.now()}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { LabelData, LabelType, SheetLayout } from './types';
import { 
    SMALL_LABEL_LAYOUT, 
    LARGE_LABEL_LAYOUT, 
    SMALL_LABEL_SKIPPED_INDICES, 
    LARGE_LABEL_SKIPPED_INDICES 
} from './constants';
import { LabelForm } from './components/LabelForm';
import { LabelSheetPreview } from './components/LabelSheetPreview';
import { ExcelImport } from './components/ExcelImport';
import { generatePdf } from './services/pdfGenerator';

const App: React.FC = () => {
    const [labelType, setLabelType] = useState<LabelType>(LabelType.Small);
    const [labelsToPrint, setLabelsToPrint] = useState<LabelData[]>([]);
    const [startIndex, setStartIndex] = useState<number>(1);
    const [activeInputTab, setActiveInputTab] = useState<'calibration' | 'generic'>('calibration');

    // Generic text state
    const [genericContent, setGenericContent] = useState('');
    const [genericFontSize, setGenericFontSize] = useState(3.5);
    const [genericIsRotated, setGenericIsRotated] = useState(false);

    // State to hold data for editing/copying to form
    const [formInitialData, setFormInitialData] = useState<Omit<LabelData, 'id'> | null>(null);

    // State for manual calibration offsets
    const [offsetX, setOffsetX] = useState<number>(0); 
    const [offsetY, setOffsetY] = useState<number>(0); 
    // State for vertical pitch accumulation fix
    const [customGapY, setCustomGapY] = useState<number>(0);

    const [error, setError] = useState<string>('');
    const [isGenerating, setIsGenerating] = useState<boolean>(false);

    // PWA Install Prompt State
    const [installPrompt, setInstallPrompt] = useState<any>(null);

    useEffect(() => {
        const handler = (e: any) => {
            e.preventDefault();
            setInstallPrompt(e);
        };
        window.addEventListener('beforeinstallprompt', handler);
        return () => window.removeEventListener('beforeinstallprompt', handler);
    }, []);

    const handleInstallClick = async () => {
        if (!installPrompt) return;
        installPrompt.prompt();
        const { outcome } = await installPrompt.userChoice;
        if (outcome === 'accepted') {
            setInstallPrompt(null);
        }
    };

    const currentLayout: SheetLayout = useMemo(() => {
        const baseLayout = labelType === LabelType.Small ? SMALL_LABEL_LAYOUT : LARGE_LABEL_LAYOUT;
        const internalBaseX = labelType === LabelType.Small ? 0.3 : 0;
        const internalBaseY = labelType === LabelType.Small ? -0.2 : 0;
        return {
            ...baseLayout,
            marginLeft: baseLayout.marginLeft + internalBaseX + offsetX,
            marginTop: baseLayout.marginTop + internalBaseY + offsetY,
            gapY: baseLayout.gapY + customGapY,
        };
    }, [labelType, offsetX, offsetY, customGapY]);

    const skippedIndices = useMemo(() => {
        return labelType === LabelType.Small ? SMALL_LABEL_SKIPPED_INDICES : LARGE_LABEL_SKIPPED_INDICES;
    }, [labelType]);

    const availableSlotsCount = useMemo(() => {
        let count = 0;
        for (let i = startIndex; i <= currentLayout.total; i++) {
            if (!skippedIndices.includes(i)) {
                count++;
            }
        }
        return count;
    }, [startIndex, currentLayout.total, skippedIndices]);

    useEffect(() => {
        const quantity = labelsToPrint.length;
        if (quantity === 0) {
            setError('');
            return;
        }
        if (startIndex < 1) {
            setError('Vị trí bắt đầu phải lớn hơn 0.');
            return;
        }
        if (quantity > availableSlotsCount) {
            setError(`Lỗi: Số tem (${quantity}) vượt quá số vị trí khả dụng còn lại (${availableSlotsCount}).`);
        } else {
            setError('');
        }
    }, [labelsToPrint, startIndex, availableSlotsCount]);

    const addLabel = (data: Omit<LabelData, 'id'>) => {
        const newLabel: LabelData = { ...data, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
        setFormInitialData(null);
    };

    const addGenericLabel = () => {
        if (!genericContent.trim()) {
            alert('Vui lòng nhập nội dung văn bản.');
            return;
        }
        const newLabel: LabelData = { 
            id: Date.now() + Math.random(),
            isGeneric: true,
            content: genericContent,
            fontSize: genericFontSize,
            isRotated: genericIsRotated
        };
        setLabelsToPrint(prev => [...prev, newLabel]);
        setGenericContent('');
        // We keep isRotated setting for next labels in the same session as it's often preferred
    };

    const duplicateLabel = (label: LabelData) => {
        const newLabel: LabelData = { ...label, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
    };

    const loadDataToForm = (label: LabelData) => {
        if (label.isGeneric) {
            setActiveInputTab('generic');
            setGenericContent(label.content || '');
            setGenericFontSize(label.fontSize || 3.5);
            setGenericIsRotated(label.isRotated || false);
        } else {
            setActiveInputTab('calibration');
            const { id, ...data } = label;
            setFormInitialData(data);
        }
    };

    const addLabelsFromExcel = (dataList: Omit<LabelData, 'id'>[]) => {
        const newLabels = dataList.map(data => ({
            ...data,
            id: Date.now() + Math.random() + Math.random()
        }));
        setLabelsToPrint(prev => [...prev, ...newLabels]);
    };

    const removeLabel = (id: number) => {
        setLabelsToPrint(prev => prev.filter(label => label.id !== id));
    };

    const clearAllLabels = () => {
        if (window.confirm('Bạn có chắc chắn muốn xóa toàn bộ danh sách tem không?')) {
            setLabelsToPrint([]);
        }
    };

    const handleGeneratePdf = async () => {
        if (error || labelsToPrint.length === 0 || isGenerating) return;
        try {
            setIsGenerating(true);
            await new Promise(resolve => setTimeout(resolve, 50));
            await generatePdf(currentLayout, labelsToPrint, startIndex);
        } catch (e) {
            console.error(e);
