import React from 'react';
import { LabelData, SheetLayout, LabelType } from '../types';

interface LabelDesignProps {
    layout: SheetLayout;
    data: LabelData;
}

const wrapText = (text: string, maxWidth: number, fontSizeMm: number) => {
    const avgCharWidth = fontSizeMm * 0.55; // Slightly tighter for better fit
    const maxChars = Math.floor(maxWidth / avgCharWidth);

    if (text.length <= maxChars && !text.includes('\n')) return [text];

    // Split by explicit newlines first
    const paragraphs = text.split('\n');
    const lines: string[] = [];

    paragraphs.forEach(p => {
        const words = p.split(' ');
        let currentLine = words[0] || '';

        for (let i = 1; i < words.length; i++) {
            const word = words[i];
            if ((currentLine + ' ' + word).length <= maxChars) {
                currentLine += ' ' + word;
            } else {
                lines.push(currentLine);
                currentLine = word;
            }
        }
        lines.push(currentLine);
    });

    return lines;
};

export const LabelDesign: React.FC<LabelDesignProps> = ({ layout, data }) => {
    const { sizeW, sizeH } = layout;

    // --- RENDER GENERIC/FREE TEXT LABEL ---
    if (data.isGeneric) {
        const fSize = data.fontSize || 3.5;
        // Logic: When rotated, the text "width" is the physical "height" of the label
        const wrapWidth = data.isRotated ? sizeH - 2 : sizeW - 2;
        const textLines = wrapText(data.content || '', wrapWidth, fSize);

        const lineHeight = fSize * 1.2;
        const totalBlockHeight = textLines.length * lineHeight;

        // Virtual dimensions for the rotated coordinate system
        const vWidth = data.isRotated ? sizeH : sizeW;
        const vHeight = data.isRotated ? sizeW : sizeH;

        // Vertical start point inside the virtual system to center the block
        const startY = (vHeight - totalBlockHeight) / 2 + (lineHeight * 0.8);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
                <rect width={sizeW} height={sizeH} fill="white" />
                <g transform={data.isRotated ? `rotate(90, ${sizeW / 2}, ${sizeH / 2})` : ''}>
                    {textLines.map((line, i) => (
                        <text 
                            key={i} 
                            x={vWidth / 2} 
                            y={startY + (i * lineHeight)} 
                            textAnchor="middle" 
                            fontSize={fSize} 
                            fontWeight="bold" 
                            fill="#000"
                        >
                            {line}
                        </text>
                    ))}
                </g>
            </svg>
        );
    }

    // --- RENDER STANDARD CALIBRATION LABEL ---
    if (layout.type === LabelType.Small) {
        const fontSize = { header: 2.6, id: 2.7, name: 1.4, date: 2.1 };
        const safeWidth = sizeW - 2.0;
        const nameLines = wrapText(data.deviceName || '', safeWidth, fontSize.name).slice(0, 3);

        return (
            <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
                <rect width={sizeW} height={sizeH} fill="white" />
                <text x={sizeW / 2} y={3.2} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>
                <line x1={2.5} y1={4.2} x2={sizeW - 2.5} y2={4.2} stroke="#000" strokeWidth="0.15" />
                <text x={sizeW / 2} y={7.2} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>
                {nameLines.map((line, i) => (
                    <text key={i} x={sizeW / 2} y={9.8 + (i * 1.7)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
                ))}
                <line x1={2.5} y1={sizeH - 6.0} x2={sizeW - 2.5} y2={sizeH - 6.0} stroke="#000" strokeWidth="0.15" opacity="0.5" />
                <text x={sizeW / 2} y={sizeH - 3.6} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>
                <text x={sizeW / 2} y={sizeH - 1.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </svg>
        );
    }

    // Large Label
    const fontSize = { header: 2.8, id: 3.8, name: 1.8, dateLabel: 1.6, date: 2.4 };
    const safeWidth = sizeW - 3;
    const nameLines = wrapText(data.deviceName || '', safeWidth, fontSize.name).slice(0, 3);

    return (
        <svg width={sizeW} height={sizeH} viewBox={`0 0 ${sizeW} ${sizeH}`} fontFamily="Arial, Helvetica, sans-serif">
            <rect width={sizeW} height={sizeH} fill="white" />
            <text x={sizeW / 2} y={5.0} textAnchor="middle" fontSize={fontSize.header} fontWeight="bold" fill="#000">JICV</text>
            <line x1={3} y1={6.5} x2={sizeW - 3} y2={6.5} stroke="black" strokeWidth="0.2" />
            <text x={sizeW / 2} y={10.5} textAnchor="middle" fontSize={fontSize.id} fontWeight="bold" fill="#000">{data.deviceId}</text>
            {nameLines.map((line, i) => (
                <text key={i} x={sizeW / 2} y={14.5 + (i * 2.2)} textAnchor="middle" fontSize={fontSize.name} fill="#000">{line}</text>
            ))}
            <g transform={`translate(0, ${sizeH - 12})`}>
                <text x={sizeW / 2} y={0.5} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Hiệu chuẩn</text>
                <text x={sizeW / 2} y={3.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.calibrationDate}</text>
                <text x={sizeW / 2} y={6.5} textAnchor="middle" fontSize={fontSize.dateLabel} fill="#555">Tiếp theo</text>
                <text x={sizeW / 2} y={9.2} textAnchor="middle" fontSize={fontSize.date} fontWeight="bold" fill="#000">{data.nextCalibrationDate}</text>
            </g>
        </svg>
    );
};

import jsPDF from 'jspdf';
import { SheetLayout, LabelData, LabelType } from '../types';
import { SMALL_LABEL_SKIPPED_INDICES, LARGE_LABEL_SKIPPED_INDICES } from '../constants';

const mmToPt = (mm: number) => mm * 2.83465;
const FONT_REGULAR_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.1.66/fonts/Roboto/Roboto-Regular.ttf';
const FONT_BOLD_URL = 'https://cdnjs.cloudflare.com/ajax/libs/pdfmake/0.1.66/fonts/Roboto/Roboto-Medium.ttf';

const loadFonts = async (pdf: jsPDF) => {
    const fetchFont = async (url: string) => {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to load font from ${url}`);
        const buffer = await response.arrayBuffer();
        let binary = '';
        const bytes = new Uint8Array(buffer);
        const len = bytes.byteLength;
        for (let i = 0; i < len; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return binary;
    };
    try {
        const [regularFont, boldFont] = await Promise.all([
            fetchFont(FONT_REGULAR_URL),
            fetchFont(FONT_BOLD_URL)
        ]);
        pdf.addFileToVFS('Roboto-Regular.ttf', regularFont);
        pdf.addFileToVFS('Roboto-Bold.ttf', boldFont);
        pdf.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
        pdf.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
        return true;
    } catch (error) {
        console.error("Error loading fonts:", error);
        return false;
    }
};

const wrapTextPdf = (text: string, maxWidthMm: number, fontSizeMm: number) => {
    const avgCharWidthMm = fontSizeMm * 0.55; 
    const maxChars = Math.floor(maxWidthMm / avgCharWidthMm);

    const paragraphs = text.split('\n');
    const lines: string[] = [];

    paragraphs.forEach(p => {
        const words = p.split(' ');
        if (words.length === 0 || (words.length === 1 && words[0] === '')) {
            lines.push('');
            return;
        }
        let currentLine = words[0];
        for (let i = 1; i < words.length; i++) {
            const word = words[i];
            if ((currentLine + ' ' + word).length <= maxChars) {
                currentLine += ' ' + word;
            } else {
                lines.push(currentLine);
                currentLine = word;
            }
        }
        lines.push(currentLine);
    });
    return lines;
};

const drawGenericLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const fSize = data.fontSize || 3.5;

    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fSize));
    pdf.setTextColor(0, 0, 0);

    const wrapWidth = data.isRotated ? sizeH - 2 : sizeW - 2;
    const lines = wrapTextPdf(data.content || '', wrapWidth, fSize);
    const lineHeight = fSize * 1.2;
    const totalBlockHeight = lines.length * lineHeight;

    const centerX = x + sizeW / 2;
    const centerY = y + sizeH / 2;

    if (data.isRotated) {
        // ROTATED 90 DEGREES
        // We calculate position for each line on a virtual vertical axis 
        // that is now the horizontal axis because of the 90 deg rotation.
        // Start offset centers the block along the original X-axis (which is now vertical).
        const startOffset = -totalBlockHeight / 2 + (lineHeight * 0.8);

        lines.forEach((line, i) => {
            // Coordinate math for jsPDF rotation:
            // x_pdf = centerX - line_offset (since lines stack 'down' the original X axis)
            // y_pdf = centerY
            // We use angle: 90 to rotate the text itself 90 deg clockwise.
            const lineX = centerX - (startOffset + i * lineHeight);
            pdf.text(line, lineX, centerY, { align: 'center', angle: 90 });
        });
    } else {
        // STANDARD
        const startY = y + (sizeH - totalBlockHeight) / 2 + (lineHeight * 0.8);
        lines.forEach((line, i) => {
            pdf.text(line, centerX, startY + (i * lineHeight), { align: 'center' });
        });
    }
};

const drawSmallLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;
    const fontSize = { header: 2.6, id: 2.7, name: 1.4, date: 2.1 };
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.header));
    pdf.text('JICV', centerX, y + 3.2, { align: 'center' });
    pdf.setLineWidth(0.15);
    pdf.line(x + 2.5, y + 4.2, x + sizeW - 2.5, y + 4.2);
    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId || '', centerX, y + 7.2, { align: 'center' });
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));
    const nameLines = wrapTextPdf(data.deviceName || '', sizeW - 2.0, fontSize.name).slice(0, 3);
    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 9.8 + (i * 1.7), { align: 'center' });
    });
    pdf.setLineWidth(0.15);
    pdf.line(x + 2.5, y + sizeH - 6.0, x + sizeW - 2.5, y + sizeH - 6.0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate || '', centerX, y + sizeH - 3.6, { align: 'center' });
    pdf.text(data.nextCalibrationDate || '', centerX, y + sizeH - 1.2, { align: 'center' });
};

const drawLargeLabel = (pdf: jsPDF, x: number, y: number, data: LabelData, layout: SheetLayout) => {
    const { sizeW, sizeH } = layout;
    const centerX = x + sizeW / 2;
    const fontSize = { header: 2.8, id: 3.8, name: 1.8, dateLabel: 1.6, date: 2.4 };
