const wrapText = (text: string, maxWidth: number, fontSizeMm: number) => {
    // 0.5 is a safer factor for Arial/Roboto to prevent overflow
    const avgCharWidth = fontSizeMm * 0.5; 
    const maxChars = Math.floor(maxWidth / avgCharWidth);

    if (text.length <= maxChars && !text.includes('\n')) return [text];

    const paragraphs = text.split('\n');
    const lines: string[] = [];

    paragraphs.forEach(p => {
        const words = p.split(' ');
        let currentLine = '';

        words.forEach(word => {
            // Force break extremely long words that exceed maxChars alone
            if (word.length > maxChars) {
                if (currentLine) lines.push(currentLine);
                let remainingWord = word;
                while (remainingWord.length > maxChars) {
                    lines.push(remainingWord.substring(0, maxChars));
                    remainingWord = remainingWord.substring(maxChars);
                }
                currentLine = remainingWord;
            } else {
                const testLine = currentLine ? currentLine + ' ' + word : word;
                if (testLine.length <= maxChars) {
                    currentLine = testLine;
                } else {
                    lines.push(currentLine);
                    currentLine = word;
                }
            }
        });
        if (currentLine) lines.push(currentLine);
    });

    return lines;
};

