const wrapText = (text: string, maxWidth: number, fontSizeMm: number) => {
    // 0.54 is a robust factor for English/Vietnamese with standard fonts
    const avgCharWidth = fontSizeMm * 0.54; 
    const maxChars = Math.max(1, Math.floor(maxWidth / avgCharWidth));

    if (text.length <= maxChars && !text.includes('\n')) return [text];

    const paragraphs = text.split('\n');
    const lines: string[] = [];

    paragraphs.forEach(p => {
        const words = p.split(' ');
        let currentLine = '';

        words.forEach(word => {
            if (word.length > maxChars) {
                if (currentLine) lines.push(currentLine);
                let rem = word;
                while (rem.length > maxChars) {
                    lines.push(rem.substring(0, maxChars));
                    rem = rem.substring(maxChars);
                }
                currentLine = rem;
            } else {
                const testLine = currentLine ? currentLine + ' ' + word : word;
                if (testLine.length <= maxChars) {
                    currentLine = testLine;
                } else {
                    lines.push(currentLine);
                    currentLine = word;
                }
            }
        });
        if (currentLine) lines.push(currentLine);
    });

    return lines;
};

