    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate || '', centerX, y + sizeH - 3.6, { align: 'center' });
    pdf.text(data.nextCalibrationDate || '', centerX, y + sizeH - 1.2, { align: 'center' });
