    pdf.setFontSize(mmToPt(fontSize.id));
    pdf.text(data.deviceId || '', centerX, y + 10.5, { align: 'center' });
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.name));
    const nameLines = wrapTextPdf(data.deviceName || '', sizeW - 3, fontSize.name).slice(0, 3);
    nameLines.forEach((line, i) => {
        pdf.text(line, centerX, y + 14.5 + (i * 2.2), { align: 'center' });
    });
    const footerY = y + sizeH - 12;
    pdf.setTextColor(80, 80, 80);
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Hiệu chuẩn', centerX, footerY + 0.5, { align: 'center' });
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.calibrationDate || '', centerX, footerY + 3.2, { align: 'center' });
    pdf.setTextColor(80, 80, 80);
    pdf.setFont('Roboto', 'normal');
    pdf.setFontSize(mmToPt(fontSize.dateLabel));
    pdf.text('Tiếp theo', centerX, footerY + 6.5, { align: 'center' });
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('Roboto', 'bold');
    pdf.setFontSize(mmToPt(fontSize.date));
    pdf.text(data.nextCalibrationDate || '', centerX, footerY + 9.2, { align: 'center' });
};

export const generatePdf = async (layout: SheetLayout, labels: LabelData[], startIndex: number) => {
    const pdf = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: [layout.paperWidth, layout.paperHeight],
    });
    const fontLoaded = await loadFonts(pdf);
    if (!fontLoaded) {
        alert("Lỗi tải font Roboto. File PDF có thể bị lỗi hiển thị tiếng Việt.");
    }
    const { cols, sizeW, sizeH, gapX, gapY, marginLeft, marginTop } = layout;
    const skippedIndices = layout.type === LabelType.Small ? SMALL_LABEL_SKIPPED_INDICES : LARGE_LABEL_SKIPPED_INDICES;
    let currentSlotIndex = startIndex;
    for (const labelData of labels) {
        while (skippedIndices.includes(currentSlotIndex)) {
            currentSlotIndex++;
        }
        if (currentSlotIndex > layout.total) break;
        const absoluteIndex0 = currentSlotIndex - 1;
        const row = Math.floor(absoluteIndex0 / cols);
        const col = absoluteIndex0 % cols;
        const x = marginLeft + col * (sizeW + gapX);
        const y = marginTop + row * (sizeH + gapY);

        if (labelData.isGeneric) {
            drawGenericLabel(pdf, x, y, labelData, layout);
        } else if (layout.type === LabelType.Small) {
            drawSmallLabel(pdf, x, y, labelData, layout);
        } else {
            drawLargeLabel(pdf, x, y, labelData, layout);
        }
        currentSlotIndex++;
    }
    pdf.save(`tem-in-${layout.type}-${Date.now()}.pdf`);
};

import React, { useState, useEffect, useMemo } from 'react';
import { LabelData, LabelType, SheetLayout } from './types';
import { 
    SMALL_LABEL_LAYOUT, 
    LARGE_LABEL_LAYOUT, 
    SMALL_LABEL_SKIPPED_INDICES, 
    LARGE_LABEL_SKIPPED_INDICES 
} from './constants';
import { LabelForm } from './components/LabelForm';
import { LabelSheetPreview } from './components/LabelSheetPreview';
import { ExcelImport } from './components/ExcelImport';
// SỬA LỖI '@/': Đảm bảo dùng đường dẫn tương đối chuẩn xác
import { generatePdf } from './services/pdfGenerator';

const App: React.FC = () => {
    const [labelType, setLabelType] = useState<LabelType>(LabelType.Small);
    const [labelsToPrint, setLabelsToPrint] = useState<LabelData[]>([]);
    const [startIndex, setStartIndex] = useState<number>(1);
    const [activeInputTab, setActiveInputTab] = useState<'calibration' | 'generic'>('calibration');

    const [genericContent, setGenericContent] = useState('');
    const [genericFontSize, setGenericFontSize] = useState(3.5);

    const [formInitialData, setFormInitialData] = useState<Omit<LabelData, 'id'> | null>(null);

    const [offsetX, setOffsetX] = useState<number>(0); 
    const [offsetY, setOffsetY] = useState<number>(0); 
    const [customGapY, setCustomGapY] = useState<number>(0);

    const [error, setError] = useState<string>('');
    const [isGenerating, setIsGenerating] = useState<boolean>(false);

    const [installPrompt, setInstallPrompt] = useState<any>(null);

    useEffect(() => {
        const handler = (e: any) => {
            e.preventDefault();
            setInstallPrompt(e);
        };
        window.addEventListener('beforeinstallprompt', handler);
        return () => window.removeEventListener('beforeinstallprompt', handler);
    }, []);

    const handleInstallClick = async () => {
        if (!installPrompt) return;
        installPrompt.prompt();
        const { outcome } = await installPrompt.userChoice;
        if (outcome === 'accepted') {
            setInstallPrompt(null);
        }
    };

    const currentLayout: SheetLayout = useMemo(() => {
        const baseLayout = labelType === LabelType.Small ? SMALL_LABEL_LAYOUT : LARGE_LABEL_LAYOUT;
        const internalBaseX = labelType === LabelType.Small ? 0.3 : 0;
        const internalBaseY = labelType === LabelType.Small ? -0.2 : 0;
        return {
            ...baseLayout,
            marginLeft: baseLayout.marginLeft + internalBaseX + offsetX,
            marginTop: baseLayout.marginTop + internalBaseY + offsetY,
            gapY: baseLayout.gapY + customGapY,
        };
    }, [labelType, offsetX, offsetY, customGapY]);

    const skippedIndices = useMemo(() => {
        return labelType === LabelType.Small ? SMALL_LABEL_SKIPPED_INDICES : LARGE_LABEL_SKIPPED_INDICES;
    }, [labelType]);

    const availableSlotsCount = useMemo(() => {
        let count = 0;
        for (let i = startIndex; i <= currentLayout.total; i++) {
            if (!skippedIndices.includes(i)) {
                count++;
            }
        }
        return count;
    }, [startIndex, currentLayout.total, skippedIndices]);

    useEffect(() => {
        const quantity = labelsToPrint.length;
        if (quantity === 0) {
            setError('');
            return;
        }
        if (startIndex < 1) {
            setError('Vị trí bắt đầu phải lớn hơn 0.');
            return;
        }
        if (quantity > availableSlotsCount) {
            setError(`Lỗi: Số tem (${quantity}) vượt quá số vị trí khả dụng còn lại (${availableSlotsCount}).`);
        } else {
            setError('');
        }
    }, [labelsToPrint, startIndex, availableSlotsCount]);

    const addLabel = (data: Omit<LabelData, 'id'>) => {
        const newLabel: LabelData = { ...data, id: Date.now() + Math.random() };
        setLabelsToPrint(prev => [...prev, newLabel]);
        setFormInitialData(null);
    };

    const addGenericLabel = () => {
        if (!genericContent.trim()) {
            alert('Vui lòng nhập nội dung văn bản.');
            return;
